//! Checks of the factor models against independent implementations: statsmodels for the
//! time-series regressions, scikit-learn for the principal components and NumPy for the
//! cross-sectional regressions. The fixture is generated by `scripts/reference/factors.py`.

#![allow(clippy::unwrap_used)]

use finalytics_risk::*;
use serde_json::Value;

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/factors.json")).unwrap()
}

fn floats(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap())
        .collect()
}

fn rows(value: &Value) -> Vec<Vec<f64>> {
    value.as_array().unwrap().iter().map(floats).collect()
}

fn strings(value: &Value) -> Vec<String> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_owned())
        .collect()
}

/// Agreement relative to the largest magnitude in the reference values.
#[track_caller]
fn close_all(actual: &[f64], expected: &[f64], tolerance: f64, what: &str) {
    assert_eq!(actual.len(), expected.len(), "{what}: lengths differ");
    let scale = expected.iter().fold(0.0f64, |m, v| m.max(v.abs()));
    for (k, (a, e)) in actual.iter().zip(expected).enumerate() {
        assert!(
            (a - e).abs() <= tolerance * scale,
            "{what}[{k}]: {a} against the reference {e}"
        );
    }
}

fn tables(f: &Value) -> (ReturnsTable, ReturnsTable) {
    let returns = ReturnsTable::new(strings(&f["assets"]), rows(&f["returns"])).unwrap();
    let factors = ReturnsTable::new(strings(&f["factors"]), rows(&f["factor_returns"])).unwrap();
    (returns, factors)
}

#[test]
fn regression_model_matches_statsmodels() {
    let f = fixture();
    let (returns, factors) = tables(&f);
    let estimate = regression_model(&returns, &factors).unwrap();
    let expected = &f["regression"];
    assert_eq!(estimate.method, FactorMethod::Regression);
    assert_eq!(estimate.model.factors(), strings(&f["factors"]).as_slice());
    let exposures: Vec<f64> = estimate.model.exposures().concat();
    close_all(
        &exposures,
        &rows(&expected["exposures"]).concat(),
        1e-11,
        "exposures",
    );
    let intercepts: Vec<f64> = estimate.fit.iter().map(|a| a.intercept.unwrap()).collect();
    close_all(
        &intercepts,
        &floats(&expected["intercepts"]),
        1e-11,
        "intercepts",
    );
    let r2: Vec<f64> = estimate.fit.iter().map(|a| a.r_squared.unwrap()).collect();
    close_all(&r2, &floats(&expected["r_squared"]), 1e-12, "r squared");
    close_all(
        estimate.model.specific_variances(),
        &floats(&expected["specific_variances"]),
        1e-12,
        "specific variances",
    );
    close_all(
        estimate.model.factor_covariance().values(),
        &floats(&expected["factor_covariance"]),
        1e-13,
        "factor covariance",
    );
}

#[test]
fn statistical_model_matches_scikit_learn() {
    let f = fixture();
    let (returns, _) = tables(&f);
    let k = f["components"].as_u64().unwrap() as usize;
    let estimate = statistical_model(&returns, k).unwrap();
    let expected = &f["statistical"];
    assert_eq!(estimate.model.factors(), ["pc1", "pc2", "pc3", "pc4"]);
    close_all(
        &estimate.model.factor_covariance().diagonal(),
        &floats(&expected["eigenvalues"]),
        1e-12,
        "eigenvalues",
    );
    close_all(
        estimate.explained_variance.as_ref().unwrap(),
        &floats(&expected["explained_variance"]),
        1e-12,
        "explained variance",
    );
    close_all(
        &estimate.model.exposures().concat(),
        &rows(&expected["exposures"]).concat(),
        1e-11,
        "loadings",
    );
    close_all(
        estimate.model.specific_variances(),
        &floats(&expected["specific_variances"]),
        1e-11,
        "specific variances",
    );
    close_all(
        &estimate.factor_returns.concat(),
        &rows(&expected["scores"]).concat(),
        1e-11,
        "scores",
    );
    let means: Vec<f64> = estimate.fit.iter().map(|a| a.intercept.unwrap()).collect();
    close_all(&means, &floats(&expected["means"]), 1e-14, "means");
}

#[test]
fn fundamental_model_matches_numpy() {
    let f = fixture();
    let (returns, _) = tables(&f);
    let factors = strings(&f["factors"]);
    let exposures = rows(&f["exposures"]);
    let estimate = fundamental_model(&returns, &factors, &exposures).unwrap();
    let expected = &f["fundamental"];
    close_all(
        &estimate.factor_returns.concat(),
        &rows(&expected["factor_returns"]).concat(),
        1e-12,
        "factor returns",
    );
    close_all(
        estimate.model.factor_covariance().values(),
        &floats(&expected["factor_covariance"]),
        1e-12,
        "factor covariance",
    );
    close_all(
        estimate.model.specific_variances(),
        &floats(&expected["specific_variances"]),
        1e-12,
        "specific variances",
    );
    let r2: Vec<f64> = estimate.fit.iter().map(|a| a.r_squared.unwrap()).collect();
    close_all(&r2, &floats(&expected["r_squared"]), 1e-12, "r squared");
}

fn reference_model(f: &Value) -> FactorModel {
    let expected = &f["regression"];
    FactorModel::new(
        strings(&f["assets"]),
        rows(&expected["exposures"]),
        Matrix::new(
            strings(&f["factors"]),
            floats(&expected["factor_covariance"]),
        )
        .unwrap(),
        floats(&expected["specific_variances"]),
    )
    .unwrap()
}

#[track_caller]
fn check_risk(risk: &FactorRisk, expected: &Value, what: &str) {
    close_all(
        &[
            risk.volatility,
            risk.factor_volatility,
            risk.specific_volatility,
            risk.specific_component,
        ],
        &[
            expected["volatility"].as_f64().unwrap(),
            expected["factor_volatility"].as_f64().unwrap(),
            expected["specific_volatility"].as_f64().unwrap(),
            expected["specific_component"].as_f64().unwrap(),
        ],
        1e-13,
        what,
    );
    let factors: Vec<f64> = risk.factors.iter().map(|c| c.component).collect();
    close_all(
        &factors,
        &floats(&expected["factor_components"]),
        1e-13,
        &format!("{what} factor components"),
    );
    let assets: Vec<f64> = risk.assets.iter().map(|c| c.component).collect();
    close_all(
        &assets,
        &floats(&expected["asset_components"]),
        1e-13,
        &format!("{what} asset components"),
    );
}

#[test]
fn factor_risk_matches_its_definition() {
    let f = fixture();
    let model = reference_model(&f);
    let weights = floats(&f["weights"]);
    let benchmark = floats(&f["benchmark"]);
    close_all(
        model.covariance().values(),
        &floats(&f["risk"]["covariance"]),
        1e-14,
        "implied covariance",
    );
    check_risk(&factor_risk(&weights, &model).unwrap(), &f["risk"], "risk");
    check_risk(
        &factor_tracking_error(&weights, &benchmark, &model).unwrap(),
        &f["tracking_error"],
        "tracking error",
    );
    let dense = risk_decomposition(&weights, &model.covariance()).unwrap();
    let risk = factor_risk(&weights, &model).unwrap();
    assert!((dense.volatility - risk.volatility).abs() < 1e-16);
}

#[test]
fn estimates_and_models_round_trip_through_json() {
    let f = fixture();
    let (returns, factors) = tables(&f);
    let estimate = regression_model(&returns, &factors).unwrap();
    let text = serde_json::to_string(&estimate).unwrap();
    let back: FactorModelEstimate = serde_json::from_str(&text).unwrap();
    assert_eq!(back, estimate);
    let mut value: Value = serde_json::to_value(&estimate.model).unwrap();
    value["specific_variances"][0] = (-1.0).into();
    let error = serde_json::from_value::<FactorModel>(value).unwrap_err();
    assert!(
        error.to_string().contains("specific_variances[0]"),
        "{error}"
    );
}

#[test]
fn inputs_are_validated() {
    let f = fixture();
    let (returns, factors) = tables(&f);
    let short = ReturnsTable::new(
        factors.labels().to_vec(),
        factors.columns().iter().map(|c| c[..10].to_vec()).collect(),
    )
    .unwrap();
    assert!(regression_model(&returns, &short).is_err());
    let collinear = ReturnsTable::new(
        vec!["x".into(), "twice x".into()],
        vec![
            factors.columns()[0].clone(),
            factors.columns()[0].iter().map(|v| 2.0 * v).collect(),
        ],
    )
    .unwrap();
    let error = regression_model(&returns, &collinear).unwrap_err();
    assert!(error.to_string().contains("twice x"), "{error}");
    assert!(statistical_model(&returns, 0).is_err());
    assert!(statistical_model(&returns, 13).is_err());
    let names = vec!["one".to_owned(), "also one".to_owned()];
    let flat = vec![vec![1.0, 1.0]; 12];
    let error = fundamental_model(&returns, &names, &flat).unwrap_err();
    assert!(error.to_string().contains("also one"), "{error}");
}
